import data from './catalogue.json';
import { findPaint } from './inventory';
import { normalizeCode, type Paint, type PaintType } from './paint';
import { SEED_INVENTORY } from './seed';

/**
 * Paint lists of Vallejo, Citadel and Army Painter, saved in the app and searched before the AI.
 * Generated by tools/gen-catalogue.py (Android repo) from Arcturus5404/miniature-paints (MIT, see
 * catalogue-LICENSE.txt); the same file ships in the Android app. Colours are approximate.
 */
export interface CatalogueEntry {
  brand: string;
  /** Maker's code; Citadel sells by name, so there the name is the code. */
  code: string;
  nameEn: string;
  range: string;
  type: PaintType;
  hex: string;
}

export const CATALOGUE: CatalogueEntry[] = (data.paints as string[][]).map(([brand, code, nameEn, range, type, hex]) => ({
  brand, code, nameEn, range, type: type as PaintType, hex,
}));

/** Lower case, no accents, single spaces: how names and queries are compared. */
const fold = (s: string) => s.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().replace(/\s+/g, ' ').trim();
const compactCode = (s: string) => fold(s).replace(/[.\s-]/g, '');

// What people (and the AI) call these makers.
const BRAND_ALIASES: Record<string, string> = {
  vallejo: 'Vallejo', 'acrylicos vallejo': 'Vallejo',
  citadel: 'Citadel', 'citadel colour': 'Citadel', 'games workshop': 'Citadel', gw: 'Citadel',
  'army painter': 'Army Painter', 'the army painter': 'Army Painter',
};
export const catalogueBrand = (brand: string): string | undefined => BRAND_ALIASES[fold(brand)];

/** The catalogue entry for a brand and code (written any way: 72010, 72.010), else by brand and name. */
export function findInCatalogue(ref: { brand: string; code?: string; name?: string }): CatalogueEntry | undefined {
  const brand = catalogueBrand(ref.brand);
  if (!brand) return undefined;
  const inBrand = CATALOGUE.filter((e) => e.brand === brand);
  const code = ref.code?.trim();
  if (code) {
    const wanted = compactCode(normalizeCode(brand, code));
    const byCode = inBrand.find((e) => compactCode(e.code) === wanted);
    if (byCode) return byCode;
  }
  const name = fold(ref.name ?? code ?? '');
  return name ? inBrand.find((e) => fold(e.nameEn) === name || fold(e.code) === name) : undefined;
}

/** Catalogue paints matching every word of the query in brand, code, name or range; exact codes first. */
export function searchCatalogue(query: string, limit = 20): CatalogueEntry[] {
  const words = fold(query).split(' ').filter(Boolean);
  if (!words.length) return [];
  const q = compactCode(query);
  const rank = (e: CatalogueEntry) => (compactCode(e.code) === q ? 0 : fold(e.nameEn).startsWith(fold(query)) ? 1 : 2);
  return CATALOGUE
    .filter((e) => {
      const hay = fold(`${e.brand} ${e.code} ${e.nameEn} ${e.range}`);
      return words.every((w) => hay.includes(w) || compactCode(e.code).includes(w.replace(/[.\s-]/g, '')));
    })
    .sort((a, b) => rank(a) - rank(b))
    .slice(0, limit);
}

/**
 * A paint from a catalogue entry. Spanish name: the one given, else the seed's for the BSL codes, else
 * the English name (the catalogue has no Spanish names).
 */
export function paintFromCatalogue(e: CatalogueEntry, spanishName?: string): Paint {
  const seed = findPaint(SEED_INVENTORY, e);
  return {
    brand: e.brand, code: e.code, name: spanishName?.trim() || seed?.name || e.nameEn,
    nameEn: e.nameEn, range: e.range, type: e.type, hex: e.hex,
  };
}

/**
 * A paint read from a photo, checked in the catalogue first: when found, the catalogue's code, English
 * name, range, type and colour win, and a Spanish name the AI gave is kept. Same rule as Android.
 */
export function lookUpInCatalogue(p: Paint): { paint: Paint; fromCatalogue: boolean } {
  const e = findInCatalogue(p);
  if (!e) return { paint: p, fromCatalogue: false };
  // The AI's name is Spanish only when it differs from the English names.
  const spanish = [e.nameEn, p.nameEn].some((en) => en && fold(en) === fold(p.name)) ? undefined : p.name;
  return { paint: paintFromCatalogue(e, spanish), fromCatalogue: true };
}
